begin;
insert into public.cefr_builtin_bank(seed_key,payload)
select item->>'seedKey',item-'seedKey' from (select $cefr_mock${"title":"Multilevel Mock 03 · School gardens","description":"Original mashq varianti: school gardens. 35 Listening, 35 Reading, 3 Writing va 8 Speaking topshirig‘i. Rasmiy test savollari emas.","level":"B1–C1","format":"multilevel","rightsConfirmed":true,"seedKey":"sinfquiz-multilevel-3","sections":[{"skill":"listening","minutes":45,"parts":[{"id":"listening-p1","title":"Short announcements","text":"Listen to eight short messages. Choose the best answer for each.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-3-part-1.mp3","imageUrl":"","questions":[{"id":"m3-l1-1","type":"choice","text":"When does the meeting begin?","options":["14:15","13:30","12:00"],"answers":["14:15"],"explanation":"The announcement says: The first message said 13:30, but the school gardens meeting now starts at 14:15."},{"id":"m3-l1-2","type":"choice","text":"Where will people meet?","options":["the town hall","the railway café","Willow School"],"answers":["Willow School"],"explanation":"The announcement says: We are meeting at Willow School. Please do not wait at the old entrance."},{"id":"m3-l1-3","type":"choice","text":"What should visitors bring?","options":["a camera","gardening gloves","a printed ticket"],"answers":["gardening gloves"],"explanation":"The announcement says: Before you leave home, remember to bring gardening gloves. Other equipment is provided."},{"id":"m3-l1-4","type":"choice","text":"What is the last day to register?","options":["Monday","the following weekend","the day after the event"],"answers":["Monday"],"explanation":"The announcement says: You can sign up until Monday. We cannot add names at the door."},{"id":"m3-l1-5","type":"choice","text":"How much is admission?","options":["five pounds","ten pounds","free"],"answers":["free"],"explanation":"The announcement says: Admission is free. The amount covers the materials, and there is no extra charge."},{"id":"m3-l1-6","type":"choice","text":"Who can answer questions?","options":["the driver","Leila","the caretaker"],"answers":["Leila"],"explanation":"The announcement says: If you have a question, ask for Leila at the information desk."},{"id":"m3-l1-7","type":"choice","text":"What did the team decide to do?","options":["move the trays beside the south window","cancel the entire project","ignore the difficulty"],"answers":["move the trays beside the south window"],"explanation":"The announcement says: Because the first seedlings received too little light, the team decided to move the trays beside the south window."},{"id":"m3-l1-8","type":"choice","text":"What is the main purpose?","options":["to sell more tickets","to replace every volunteer","growing food in small spaces"],"answers":["growing food in small spaces"],"explanation":"The announcement says: We are doing this to support growing food in small spaces, not simply to advertise the event."}]},{"id":"listening-p2","title":"Briefing notes","text":"Listen to the briefing. Complete the notes with one word or number.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-3-part-2.mp3","imageUrl":"","questions":[{"id":"m3-l2-1","type":"text","text":"Which day is the briefing held? Write ONE word or number.","options":[],"answers":["Tuesday"],"explanation":"The briefing explicitly gives Tuesday."},{"id":"m3-l2-2","type":"text","text":"What time does the briefing start? Write ONE word or number.","options":[],"answers":["14:15"],"explanation":"The briefing explicitly gives 14:15."},{"id":"m3-l2-3","type":"text","text":"Who leads the first session? Write ONE word or number.","options":[],"answers":["Leila"],"explanation":"The briefing explicitly gives Leila."},{"id":"m3-l2-4","type":"text","text":"What is the registration deadline? Write ONE word or number.","options":[],"answers":["Monday"],"explanation":"The briefing explicitly gives Monday."},{"id":"m3-l2-5","type":"text","text":"How many entries were recorded? Write ONE word or number.","options":[],"answers":["4"],"explanation":"The briefing explicitly gives 4."},{"id":"m3-l2-6","type":"text","text":"Which word describes the main concern? Write ONE word or number.","options":[],"answers":["sunlight"],"explanation":"The briefing explicitly gives sunlight."}]},{"id":"listening-p3","title":"Four speakers","text":"Match four speakers with the main ideas. Two options are extra.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-3-part-3.mp3","imageUrl":"","questions":[{"id":"m3-l3-1","type":"choice","text":"Match speaker 1 with the main idea.","options":["Planning the next stage","Finding a sponsor","Rejecting the whole project","Personal motivation","Learning from a setback","Cautious optimism about a result"],"answers":["Personal motivation"],"explanation":"Speaker 1 focuses on personal motivation."},{"id":"m3-l3-2","type":"choice","text":"Match speaker 2 with the main idea.","options":["Finding a sponsor","Rejecting the whole project","Personal motivation","Learning from a setback","Cautious optimism about a result","Planning the next stage"],"answers":["Learning from a setback"],"explanation":"Speaker 2 focuses on learning from a setback."},{"id":"m3-l3-3","type":"choice","text":"Match speaker 3 with the main idea.","options":["Rejecting the whole project","Personal motivation","Learning from a setback","Cautious optimism about a result","Planning the next stage","Finding a sponsor"],"answers":["Cautious optimism about a result"],"explanation":"Speaker 3 focuses on cautious optimism about a result."},{"id":"m3-l3-4","type":"choice","text":"Match speaker 4 with the main idea.","options":["Personal motivation","Learning from a setback","Cautious optimism about a result","Planning the next stage","Finding a sponsor","Rejecting the whole project"],"answers":["Planning the next stage"],"explanation":"Speaker 4 focuses on planning the next stage."}]},{"id":"listening-p4","title":"Responding to requests","text":"Match each request to the response. Three options are extra.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-3-part-4.mp3","imageUrl":"","questions":[{"id":"m3-l4-1","type":"choice","text":"Which response was given to a visitor who cannot reach the upper floor?","options":["Explain the sample limitation","Read the equipment list","Buy a new ticket immediately","Send the report to a newspaper","Replace all volunteers","Move activities to an accessible room","Check the revised schedule","Help plan a follow-up session"],"answers":["Move activities to an accessible room"],"explanation":"The announcement connects this request with “move activities to an accessible room”."},{"id":"m3-l4-2","type":"choice","text":"Which response was given to a volunteer who needs to know the arrival time?","options":["Read the equipment list","Buy a new ticket immediately","Send the report to a newspaper","Replace all volunteers","Move activities to an accessible room","Check the revised schedule","Help plan a follow-up session","Explain the sample limitation"],"answers":["Check the revised schedule"],"explanation":"The announcement connects this request with “check the revised schedule”."},{"id":"m3-l4-3","type":"choice","text":"Which response was given to someone who wants the project to continue?","options":["Buy a new ticket immediately","Send the report to a newspaper","Replace all volunteers","Move activities to an accessible room","Check the revised schedule","Help plan a follow-up session","Explain the sample limitation","Read the equipment list"],"answers":["Help plan a follow-up session"],"explanation":"The announcement connects this request with “help plan a follow-up session”."},{"id":"m3-l4-4","type":"choice","text":"Which response was given to a researcher questioning the findings?","options":["Send the report to a newspaper","Replace all volunteers","Move activities to an accessible room","Check the revised schedule","Help plan a follow-up session","Explain the sample limitation","Read the equipment list","Buy a new ticket immediately"],"answers":["Explain the sample limitation"],"explanation":"The announcement connects this request with “explain the sample limitation”."},{"id":"m3-l4-5","type":"choice","text":"Which response was given to a participant with an item to bring?","options":["Replace all volunteers","Move activities to an accessible room","Check the revised schedule","Help plan a follow-up session","Explain the sample limitation","Read the equipment list","Buy a new ticket immediately","Send the report to a newspaper"],"answers":["Read the equipment list"],"explanation":"The announcement connects this request with “read the equipment list”."}]},{"id":"listening-p5","title":"Three conversations","text":"Listen to three conversations. Answer two questions about each.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-3-part-5.mp3","imageUrl":"","questions":[{"id":"m3-l5-1","type":"choice","text":"Why is the speaker cautious?","options":["the project did not measure soil quality","There was no trial.","The report was lost."],"answers":["the project did not measure soil quality"],"explanation":"Conversation 1 states this clearly."},{"id":"m3-l5-2","type":"choice","text":"What does the speaker recommend?","options":["closing the project","buying a larger room","another trial"],"answers":["another trial"],"explanation":"Conversation 1 states this clearly."},{"id":"m3-l5-3","type":"choice","text":"Which option does the second speaker prefer?","options":["decorative paving","neither option","rainwater collection"],"answers":["rainwater collection"],"explanation":"Conversation 2 states this clearly."},{"id":"m3-l5-4","type":"choice","text":"Why does the speaker prefer it?","options":["it needs no volunteers","growing food in small spaces","it is the oldest option"],"answers":["growing food in small spaces"],"explanation":"Conversation 2 states this clearly."},{"id":"m3-l5-5","type":"choice","text":"Who will speak?","options":["the caretaker","Leila","the driver"],"answers":["Leila"],"explanation":"Conversation 3 states this clearly."},{"id":"m3-l5-6","type":"choice","text":"Why did the plan change?","options":["the first seedlings received too little light","a lack of interest","a change in the weather forecast"],"answers":["the first seedlings received too little light"],"explanation":"Conversation 3 states this clearly."}]},{"id":"listening-p6","title":"Project lecture","text":"Listen to the lecture and write one word or number for each answer.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-3-part-6.mp3","imageUrl":"","questions":[{"id":"m3-l6-1","type":"text","text":"What do the collected records form? Write ONE word or number.","options":[],"answers":["evidence"],"explanation":"The lecture uses the word evidence."},{"id":"m3-l6-2","type":"text","text":"What is the total highlighted in the report? Write ONE word or number.","options":[],"answers":["4"],"explanation":"The lecture uses the word 4."},{"id":"m3-l6-3","type":"text","text":"Which word describes the key idea? Write ONE word or number.","options":[],"answers":["sunlight"],"explanation":"The lecture uses the word sunlight."},{"id":"m3-l6-4","type":"text","text":"What did the team ask visitors for? Write ONE word or number.","options":[],"answers":["feedback"],"explanation":"The lecture uses the word feedback."},{"id":"m3-l6-5","type":"text","text":"What must be understood behind a result? Write ONE word or number.","options":[],"answers":["conditions"],"explanation":"The lecture uses the word conditions."},{"id":"m3-l6-6","type":"text","text":"Which section contains the final interpretation? Write ONE word or number.","options":[],"answers":["conclusions"],"explanation":"The lecture uses the word conclusions."}]}]},{"skill":"reading","minutes":60,"parts":[{"id":"reading-p1","title":"One-word gaps","text":"The school gardens project depended on (1) ____ who gave their time freely. At first, the team followed a fixed (2) ____, but the first seedlings received too little light. Careful (3) ____ showed exactly when the difficulty appeared. The organisers asked visitors for (4) ____ before changing the plan. They also wanted better (5) ____ for people who could not use the first arrangement. In the end, the strongest (6) ____ came from weekly notes from four classes. None of these observations proves that the same approach would work in every town. Nevertheless, the group learned why small, well-recorded changes can matter. Its next meeting will consider whether share seedlings with nearby schools is practical and who could help.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m3-r1-1","type":"text","text":"Complete gap 1 with ONE word.","options":[],"answers":["volunteers"],"explanation":"“volunteers” makes the sentence grammatically and logically complete."},{"id":"m3-r1-2","type":"text","text":"Complete gap 2 with ONE word.","options":[],"answers":["schedule"],"explanation":"“schedule” makes the sentence grammatically and logically complete."},{"id":"m3-r1-3","type":"text","text":"Complete gap 3 with ONE word.","options":[],"answers":["records"],"explanation":"“records” makes the sentence grammatically and logically complete."},{"id":"m3-r1-4","type":"text","text":"Complete gap 4 with ONE word.","options":[],"answers":["feedback"],"explanation":"“feedback” makes the sentence grammatically and logically complete."},{"id":"m3-r1-5","type":"text","text":"Complete gap 5 with ONE word.","options":[],"answers":["access"],"explanation":"“access” makes the sentence grammatically and logically complete."},{"id":"m3-r1-6","type":"text","text":"Complete gap 6 with ONE word.","options":[],"answers":["evidence"],"explanation":"“evidence” makes the sentence grammatically and logically complete."}]},{"id":"reading-p2","title":"Notices and needs","text":"A. Guided introduction: meet Leila at Willow School on Tuesday.\nB. Quiet hour: a smaller group meets before the main session.\nC. Access help: ask about step-free rooms and larger-print information.\nD. Skills desk: volunteers demonstrate practical methods and tools.\nE. Family visit: activities are planned for adults and children together.\nF. Research corner: examine the report and ask how information was collected.\nG. Follow-up team: help organise share seedlings with nearby schools.\nH. Short briefing: Leila gives a twenty-minute overview.\nI. Merchandise desk: souvenirs are available after the event.\nJ. Private room hire: businesses can book an unrelated meeting.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m3-r2-1","type":"choice","text":"Which notice suits this person? A visitor wants a guided introduction.","options":["D","E","F","G","H","I","J","A","B","C"],"answers":["A"],"explanation":"Notice A offers exactly this service."},{"id":"m3-r2-2","type":"choice","text":"Which notice suits this person? Someone prefers a smaller, quieter group.","options":["E","F","G","H","I","J","A","B","C","D"],"answers":["B"],"explanation":"Notice B offers exactly this service."},{"id":"m3-r2-3","type":"choice","text":"Which notice suits this person? A person needs access information.","options":["F","G","H","I","J","A","B","C","D","E"],"answers":["C"],"explanation":"Notice C offers exactly this service."},{"id":"m3-r2-4","type":"choice","text":"Which notice suits this person? A learner wants a hands-on demonstration.","options":["G","H","I","J","A","B","C","D","E","F"],"answers":["D"],"explanation":"Notice D offers exactly this service."},{"id":"m3-r2-5","type":"choice","text":"Which notice suits this person? A parent wants to bring a child.","options":["H","I","J","A","B","C","D","E","F","G"],"answers":["E"],"explanation":"Notice E offers exactly this service."},{"id":"m3-r2-6","type":"choice","text":"Which notice suits this person? A visitor wants to inspect the evidence.","options":["I","J","A","B","C","D","E","F","G","H"],"answers":["F"],"explanation":"Notice F offers exactly this service."},{"id":"m3-r2-7","type":"choice","text":"Which notice suits this person? A resident wants to help with the next event.","options":["J","A","B","C","D","E","F","G","H","I"],"answers":["G"],"explanation":"Notice G offers exactly this service."},{"id":"m3-r2-8","type":"choice","text":"Which notice suits this person? Someone has only twenty minutes available.","options":["A","B","C","D","E","F","G","H","I","J"],"answers":["H"],"explanation":"Notice H offers exactly this service."}]},{"id":"reading-p3","title":"Paragraph headings","text":"Headings: A. The original difficulty | B. A practical adjustment | C. Collecting information | D. What the figures show | E. A reason for caution | F. The next question | G. A celebrity endorsement | H. An unrelated invention\n\nA. The idea behind school gardens began with growing food in small spaces. People welcomed the aim, but the first arrangement was less reliable than the team expected. In particular, the first seedlings received too little light. Several participants described this as a problem of planning rather than a reason to abandon the work. Their observations were recorded instead of being dismissed.\n\nB. The organisers compared a complicated solution with a manageable one. They chose to move the trays beside the south window. This did not remove every difficulty, yet it made the next session possible without asking volunteers to start again. Leila then explained the revised procedure to participants, including those who had missed the first announcement.\n\nC. Good intentions alone could not tell the team whether the change helped. They gathered weekly notes from four classes and kept notes about the conditions under which each observation was made. When a record was incomplete, they marked it as uncertain rather than filling in a likely answer. This made the report less dramatic but more useful.\n\nD. According to the team, most herbs recovered within three weeks. The figure attracted attention because it described an observable outcome, not merely a prediction. It also encouraged more residents to ask how they could take part. However, a number by itself says little about the people or circumstances behind it.\n\nE. The report acknowledges that the project did not measure soil quality. A different location, season or group of participants might produce a different result. The team therefore resisted a claim that its method was universally successful. This careful interpretation helped readers separate the evidence from the organisers' hopes.\n\nF. The final recommendation was to share seedlings with nearby schools. Before doing so, the organisers want to agree on clear measures of success and an accessible way to collect comments. They also plan to compare rainwater collection with decorative paving rather than assuming one choice will be best for every participant.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m3-r3-1","type":"choice","text":"Choose a heading for paragraph A.","options":["What the figures show","A reason for caution","The next question","A celebrity endorsement","An unrelated invention","The original difficulty","A practical adjustment","Collecting information"],"answers":["The original difficulty"],"explanation":"Paragraph A develops the idea “the original difficulty”."},{"id":"m3-r3-2","type":"choice","text":"Choose a heading for paragraph B.","options":["A reason for caution","The next question","A celebrity endorsement","An unrelated invention","The original difficulty","A practical adjustment","Collecting information","What the figures show"],"answers":["A practical adjustment"],"explanation":"Paragraph B develops the idea “a practical adjustment”."},{"id":"m3-r3-3","type":"choice","text":"Choose a heading for paragraph C.","options":["The next question","A celebrity endorsement","An unrelated invention","The original difficulty","A practical adjustment","Collecting information","What the figures show","A reason for caution"],"answers":["Collecting information"],"explanation":"Paragraph C develops the idea “collecting information”."},{"id":"m3-r3-4","type":"choice","text":"Choose a heading for paragraph D.","options":["A celebrity endorsement","An unrelated invention","The original difficulty","A practical adjustment","Collecting information","What the figures show","A reason for caution","The next question"],"answers":["What the figures show"],"explanation":"Paragraph D develops the idea “what the figures show”."},{"id":"m3-r3-5","type":"choice","text":"Choose a heading for paragraph E.","options":["An unrelated invention","The original difficulty","A practical adjustment","Collecting information","What the figures show","A reason for caution","The next question","A celebrity endorsement"],"answers":["A reason for caution"],"explanation":"Paragraph E develops the idea “a reason for caution”."},{"id":"m3-r3-6","type":"choice","text":"Choose a heading for paragraph F.","options":["The original difficulty","A practical adjustment","Collecting information","What the figures show","A reason for caution","The next question","A celebrity endorsement","An unrelated invention"],"answers":["The next question"],"explanation":"Paragraph F develops the idea “the next question”."}]},{"id":"reading-p4","title":"Detailed article","text":"An invitation to take part in school gardens appeared at Willow School. Its stated aim was growing food in small spaces. The first public meeting was held on Tuesday, and Leila collected the comments. Early reports suggested enthusiasm, but the team also heard practical concerns. Most notably, the first seedlings received too little light. It would have been easy to present this as a minor inconvenience. Instead, the organisers documented it and chose to move the trays beside the south window.\n\nThe revised activity did not follow exactly the original schedule. The organisers tested the change, recorded weekly notes from four classes, and compared comments made before and after the adjustment. Their report states that most herbs recovered within three weeks. The authors are careful to explain the difference between an observation and a prediction: a positive first month does not guarantee a positive first year.\n\nTwo alternatives were discussed. Some participants supported rainwater collection; others preferred decorative paving. Neither option was dismissed without consideration. The report ultimately recommended a limited further trial rather than an immediate permanent decision. Its main reservation was that the project did not measure soil quality. Leila said that the next stage would be to share seedlings with nearby schools.\n\nThe report does not give the ages of the visitors, the exact amount of any future grant, or a date for publishing a second edition. Those details may matter later, but a reader should not invent them now. The value of the project lies partly in its willingness to say what remains unknown.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m3-r4-1","type":"choice","text":"What was the stated aim of the project?","options":["to close the venue","growing food in small spaces","to sell souvenirs","to replace public transport"],"answers":["growing food in small spaces"],"explanation":"The opening paragraph states the aim."},{"id":"m3-r4-2","type":"choice","text":"What led the organisers to revise the activity?","options":["the first seedlings received too little light","a new mayor","a cancelled newspaper","a competition prize"],"answers":["the first seedlings received too little light"],"explanation":"The reported problem led directly to the adjustment."},{"id":"m3-r4-3","type":"choice","text":"Which action did the organisers take?","options":["stop collecting comments","claim guaranteed success","ignore accessibility","move the trays beside the south window"],"answers":["move the trays beside the south window"],"explanation":"The revised action is explicitly described."},{"id":"m3-r4-4","type":"choice","text":"How do the authors treat the positive early result?","options":["As an error to hide","As irrelevant to the project","As useful but limited evidence","As proof for every community"],"answers":["As useful but limited evidence"],"explanation":"The text distinguishes observation from prediction."},{"id":"m3-r4-5","type":"choice","text":"True / False / Not Given: The team recorded information during the revised activity.","options":["True","False","Not Given"],"answers":["True"],"explanation":"The second paragraph says the team recorded evidence."},{"id":"m3-r4-6","type":"choice","text":"True / False / Not Given: The organisers permanently rejected both alternatives.","options":["False","Not Given","True"],"answers":["False"],"explanation":"Both alternatives were considered; a further trial was recommended."},{"id":"m3-r4-7","type":"choice","text":"True / False / Not Given: Every visitor was younger than eighteen.","options":["Not Given","True","False"],"answers":["Not Given"],"explanation":"No ages are supplied."},{"id":"m3-r4-8","type":"choice","text":"True / False / Not Given: The report identifies a limitation of the trial.","options":["True","False","Not Given"],"answers":["True"],"explanation":"The report acknowledges a limitation."},{"id":"m3-r4-9","type":"choice","text":"True / False / Not Given: A second edition will be published next month.","options":["False","Not Given","True"],"answers":["Not Given"],"explanation":"No date for a second edition is given."}]},{"id":"reading-p5","title":"Analysis and inference","text":"The organisers at Willow School made a useful distinction between a change that is easy to announce and a change that can be evaluated. Their focus was growing food in small spaces. During the first stage, the first seedlings received too little light. The immediate response was to move the trays beside the south window, but the team did not describe this response as a complete solution.\n\nTo check what happened, they collected weekly notes from four classes. The report highlighted a figure of 4. A short account of the trial was sent to Leila, who asked for more information about the conditions in which it took place. In particular, the project did not measure soil quality. This mattered because an impressive number from a narrow trial can be misleading when removed from its context.\n\nAt the next meeting, participants will compare rainwater collection with decorative paving. They will also consider how to share seedlings with nearby schools. The discussion is designed to invite disagreement supported by reasons, not to reward the loudest speaker. If the group can repeat the trial and explain its limitations clearly, the result will be more useful to other communities.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m3-r5-1","type":"text","text":"Which venue hosted the organisers? Write ONE word from the venue name.","options":[],"answers":["Willow"],"explanation":"The venue starts with Willow."},{"id":"m3-r5-2","type":"text","text":"What figure did the report highlight? Write ONE number.","options":[],"answers":["4"],"explanation":"The figure given is 4."},{"id":"m3-r5-3","type":"text","text":"Who requested more information? Write ONE name.","options":[],"answers":["Leila"],"explanation":"The text names Leila."},{"id":"m3-r5-4","type":"text","text":"What can be misleading without context? Write ONE word.","options":[],"answers":["number"],"explanation":"The passage describes an impressive number from a narrow trial."},{"id":"m3-r5-5","type":"choice","text":"Why does the writer mention the limitation?","options":["To hide the report","To prevent an overconfident conclusion","To argue that evidence is useless","To avoid hearing from participants"],"answers":["To prevent an overconfident conclusion"],"explanation":"The writer warns against removing the result from context."},{"id":"m3-r5-6","type":"choice","text":"What attitude does the final paragraph encourage?","options":["Reasoned disagreement","Silence at meetings","Immediate approval of every idea","Competition for attention"],"answers":["Reasoned disagreement"],"explanation":"The group invites disagreement supported by reasons."}]}]},{"skill":"writing","minutes":60,"parts":[{"id":"writing-p1","title":"Tasks 1.1, 1.2 and 2","text":"Write all three responses. Your work is assessed by an administrator.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m3-w1","type":"writing","text":"You and a friend attended an activity about school gardens. Write an informal message to your friend. Explain what you enjoyed and suggest one thing to do next. Aim for about 50 words.","options":[],"answers":[],"explanation":""},{"id":"m3-w2","type":"writing","text":"Write to Leila, the organiser at Willow School. Explain why you attended, describe the difficulty (“the first seedlings received too little light”), and suggest a practical improvement. Use a suitable formal tone. Aim for about 120–150 words.","options":[],"answers":[],"explanation":""},{"id":"m3-w3","type":"writing","text":"Some people think communities should invest in rainwater collection; others prefer decorative paving. Discuss both views and explain which approach would better support growing food in small spaces. Give reasons and examples. Aim for about 180–220 words.","options":[],"answers":[],"explanation":""}]}]},{"skill":"speaking","minutes":15,"parts":[{"id":"speaking-p1","title":"Part 1.1 — personal questions","text":"Record one answer per prompt.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m3-s1-1","type":"speaking","text":"What do you enjoy doing in your neighbourhood?","options":[],"answers":[],"explanation":""},{"id":"m3-s1-2","type":"speaking","text":"How do you usually learn about local events?","options":[],"answers":[],"explanation":""},{"id":"m3-s1-3","type":"speaking","text":"Have you ever visited a place like Willow School?","options":[],"answers":[],"explanation":""}]},{"id":"speaking-p2","title":"Part 1.2 — compare two scenes","text":"Scene A: a small group working together. Scene B: a large public presentation. Compare the two situations.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m3-s2-1","type":"speaking","text":"Compare a small group discussion at Willow School with a large public meeting. What might each be like?","options":[],"answers":[],"explanation":""},{"id":"m3-s2-2","type":"speaking","text":"Which setting would help people discuss school gardens more effectively, and why?","options":[],"answers":[],"explanation":""},{"id":"m3-s2-3","type":"speaking","text":"Would your preference change if you were presenting rather than listening?","options":[],"answers":[],"explanation":""}]},{"id":"speaking-p3","title":"Part 2 — extended answer","text":"Prepare for one minute; speak for about two minutes.","source":"